export function getWordsByCategory(category: WordCategoryIT): VocabularyWord[] {
  return vocabulary.filter((w) => w.category === category)
}

export function getWordsByLevel(level: CEFRLevel): VocabularyWord[] {
  return vocabulary.filter((w) => w.level === level)
}

export function searchWords(query: string): VocabularyWord[] {
  const q = query.toLowerCase()
  return vocabulary.filter(
    (w) =>
      w.word.toLowerCase().includes(q) ||
      w.definition.toLowerCase().includes(q) ||
      w.tags.some((t) => t.toLowerCase().includes(q))
  )
}
